void zscanCommand(client *c) {
    robj *o;
    unsigned long cursor;

    if (parseScanCursorOrReply(c,c->argv[2],&cursor) == C_ERR) return;
    if ((o = lookupKeyReadOrReply(c,c->argv[1],shared.emptyscan)) == NULL ||
        checkType(c,o,OBJ_ZSET)) return;
    scanGenericCommand(c,o,cursor);
}

/* This command implements the generic zpop operation, used by:
 * ZPOPMIN, ZPOPMAX, BZPOPMIN, BZPOPMAX and ZMPOP. This function is also used
 * inside blocked.c in the unblocking stage of BZPOPMIN, BZPOPMAX and BZMPOP.
 *
 * If 'emitkey' is true also the key name is emitted, useful for the blocking
 * behavior of BZPOP[MIN|MAX], since we can block into multiple keys.
 * Or in ZMPOP/BZMPOP, because we also can take multiple keys.
 *
 * 'count' is the number of elements requested to pop, or -1 for plain single pop.
 *
 * 'use_nested_array' when false it generates a flat array (with or without key name).
 * When true, it generates a nested 2 level array of field + score pairs, or 3 level when emitkey is set.
 *
 * 'reply_nil_when_empty' when true we reply a NIL if we are not able to pop up any elements.
 * Like in ZMPOP/BZMPOP we reply with a structured nested array containing key name
 * and member + score pairs. In these commands, we reply with null when we have no result.
 * Otherwise in ZPOPMIN/ZPOPMAX we reply an empty array by default.
 *
 * 'deleted' is an optional output argument to get an indication
 * if the key got deleted by this function.
 * */
void genericZpopCommand(client *c, robj **keyv, int keyc, int where, int emitkey,
                        long count, int use_nested_array, int reply_nil_when_empty, int *deleted) {
    int idx;
    robj *key = NULL;
    robj *zobj = NULL;
    sds ele;
    double score;

    if (deleted) *deleted = 0;

    /* Check type and break on the first error, otherwise identify candidate. */
    idx = 0;
    while (idx < keyc) {
        key = keyv[idx++];
        zobj = lookupKeyWrite(c->db,key);
        if (!zobj) continue;
        if (checkType(c,zobj,OBJ_ZSET)) return;
        break;
    }

    /* No candidate for zpopping, return empty. */
    if (!zobj) {
        if (reply_nil_when_empty) {
            addReplyNullArray(c);
        } else {
            addReply(c,shared.emptyarray);
        }
        return;
    }

    if (count == 0) {
        /* ZPOPMIN/ZPOPMAX with count 0. */
        addReply(c, shared.emptyarray);
        return;
    }

    long result_count = 0;

    /* When count is -1, we need to correct it to 1 for plain single pop. */
    if (count == -1) count = 1;

    long llen = zsetLength(zobj);
    long rangelen = (count > llen) ? llen : count;

    if (!use_nested_array && !emitkey) {
        /* ZPOPMIN/ZPOPMAX with or without COUNT option in RESP2. */
        addReplyArrayLen(c, rangelen * 2);
    } else if (use_nested_array && !emitkey) {
        /* ZPOPMIN/ZPOPMAX with COUNT option in RESP3. */
        addReplyArrayLen(c, rangelen);
    } else if (!use_nested_array && emitkey) {
        /* BZPOPMIN/BZPOPMAX in RESP2 and RESP3. */
        addReplyArrayLen(c, rangelen * 2 + 1);
        addReplyBulk(c, key);
    } else if (use_nested_array && emitkey) {
        /* ZMPOP/BZMPOP in RESP2 and RESP3. */
        addReplyArrayLen(c, 2);
        addReplyBulk(c, key);
        addReplyArrayLen(c, rangelen);
    }

    /* Remove the element. */
    do {
        if (zobj->encoding == OBJ_ENCODING_LISTPACK) {
            unsigned char *zl = zobj->ptr;
            unsigned char *eptr, *sptr;
            unsigned char *vstr;
            unsigned int vlen;
            long long vlong;

            /* Get the first or last element in the sorted set. */
            eptr = lpSeek(zl,where == ZSET_MAX ? -2 : 0);
            serverAssertWithInfo(c,zobj,eptr != NULL);
            vstr = lpGetValue(eptr,&vlen,&vlong);
            if (vstr == NULL)
                ele = sdsfromlonglong(vlong);
            else
                ele = sdsnewlen(vstr,vlen);

            /* Get the score. */
            sptr = lpNext(zl,eptr);
            serverAssertWithInfo(c,zobj,sptr != NULL);
            score = zzlGetScore(sptr);
        } else if (zobj->encoding == OBJ_ENCODING_SKIPLIST) {
            zset *zs = zobj->ptr;
            zskiplist *zsl = zs->zsl;
            zskiplistNode *zln;

            /* Get the first or last element in the sorted set. */
            zln = (where == ZSET_MAX ? zsl->tail :
                                       zsl->header->level[0].forward);

            /* There must be an element in the sorted set. */
            serverAssertWithInfo(c,zobj,zln != NULL);
            ele = sdsdup(zln->ele);
            score = zln->score;
        } else {
            serverPanic("Unknown sorted set encoding");
        }

        serverAssertWithInfo(c,zobj,zsetDel(zobj,ele));
        server.dirty++;

        if (result_count == 0) { /* Do this only for the first iteration. */
            char *events[2] = {"zpopmin","zpopmax"};
            notifyKeyspaceEvent(NOTIFY_ZSET,events[where],key,c->db->id);
            signalModifiedKey(c,c->db,key);
        }

        if (use_nested_array) {
            addReplyArrayLen(c,2);
        }
        addReplyBulkCBuffer(c,ele,sdslen(ele));
        addReplyDouble(c,score);
        sdsfree(ele);
        ++result_count;
    } while(--rangelen);

    /* Remove the key, if indeed needed. */
    if (zsetLength(zobj) == 0) {
        if (deleted) *deleted = 1;

        dbDelete(c->db,key);
        notifyKeyspaceEvent(NOTIFY_GENERIC,"del",key,c->db->id);
    }

    if (c->cmd->proc == zmpopCommand) {
        /* Always replicate it as ZPOP[MIN|MAX] with COUNT option instead of ZMPOP. */
        robj *count_obj = createStringObjectFromLongLong((count > llen) ? llen : count);
        rewriteClientCommandVector(c, 3,
                                   (where == ZSET_MAX) ? shared.zpopmax : shared.zpopmin,
                                   key, count_obj);
        decrRefCount(count_obj);
    }
}

/* ZPOPMIN/ZPOPMAX key [<count>] */
void zpopMinMaxCommand(client *c, int where) {
    if (c->argc > 3) {
        addReplyErrorObject(c,shared.syntaxerr);
        return;
    }

    long count = -1; /* -1 for plain single pop. */
    if (c->argc == 3 && getPositiveLongFromObjectOrReply(c, c->argv[2], &count, NULL) != C_OK)
        return;

    /* Respond with a single (flat) array in RESP2 or if count is -1
     * (returning a single element). In RESP3, when count > 0 use nested array. */
    int use_nested_array = (c->resp > 2 && count != -1);

    genericZpopCommand(c, &c->argv[1], 1, where, 0, count, use_nested_array, 0, NULL);
}

/* ZPOPMIN key [<count>] */
void zpopminCommand(client *c) {
    zpopMinMaxCommand(c, ZSET_MIN);
}

/* ZPOPMAX key [<count>] */
void zpopmaxCommand(client *c) {
    zpopMinMaxCommand(c, ZSET_MAX);
}

/* BZPOPMIN, BZPOPMAX, BZMPOP actual implementation.
 *
 * 'numkeys' is the number of keys.
 *
 * 'timeout_idx' parameter position of block timeout.
 *
 * 'where' ZSET_MIN or ZSET_MAX.
 *
 * 'count' is the number of elements requested to pop, or -1 for plain single pop.
 *
 * 'use_nested_array' when false it generates a flat array (with or without key name).
 * When true, it generates a nested 3 level array of keyname, field + score pairs.
 * */
void blockingGenericZpopCommand(client *c, robj **keys, int numkeys, int where,
                                int timeout_idx, long count, int use_nested_array, int reply_nil_when_empty) {
    robj *o;
    robj *key;
    robj *timeoutobj;
    robj *popcmd;
    mstime_t timeout;
    long double timeout_ld;
    long long timeout_ms;
    int j;

    UNUSED(reply_nil_when_empty);

    /* Parse the timeout argument in seconds and convert it to an absolute
     * millisecond timestamp. A zero timeout means block forever. */
    timeoutobj = c->argv[timeout_idx];
    timeout_ld = 0;
    if (timeoutobj == NULL) {
        timeout_ld = 0;
    } else {
        serverAssertWithInfo(NULL,timeoutobj,timeoutobj->type == OBJ_STRING);
        if (sdsEncodedObject(timeoutobj)) {
            if (!string2ld(timeoutobj->ptr, sdslen(timeoutobj->ptr), &timeout_ld)) {
                addReplyError(c,"timeout is not a float or out of range");
                return;
            }
        } else if (timeoutobj->encoding == OBJ_ENCODING_INT) {
            timeout_ld = (long)timeoutobj->ptr;
        } else {
            serverPanic("Unknown string encoding");
        }
    }
    timeout_ms = (long long) (timeout_ld * 1000.0);
    if (timeout_ms < 0) {
        addReplyError(c,"timeout is negative");
        return;
    }
    if (timeout_ms > 0) {
        timeout_ms += mstime();
    }
    timeout = timeout_ms;

    for (j = 0; j < numkeys; j++) {
        dictEntry *de;
        robj *val;
        int is_ro_replica;
        int force_delete_expired;
        unsigned long llen;
        long pop_count;
        long rangelen;
        long result_count;
        sds ele;
        double score;

        key = keys[j];

        /* Locate the key for writing, expire it if needed, and refresh LRU/LFU. */
        de = dictFind(c->db->dict, key->ptr);
        val = NULL;
        if (de != NULL) {
            val = dictGetVal(de);
            is_ro_replica = server.masterhost && server.repl_slave_ro;
            force_delete_expired = !is_ro_replica;
            if (keyIsExpired(c->db, key)) {
                if (server.masterhost != NULL) {
                    if (server.current_client == server.master) {
                        /* Keep the key while a replica applies a master command. */
                    } else if (!force_delete_expired) {
                        val = NULL;
                    } else {
                        if (checkClientPauseTimeoutAndReturnIfPaused()) {
                            val = NULL;
                        } else {
                            deleteExpiredKeyAndPropagate(c->db, key);
                            val = NULL;
                        }
                    }
                } else {
                    if (checkClientPauseTimeoutAndReturnIfPaused()) {
                        val = NULL;
                    } else {
                        deleteExpiredKeyAndPropagate(c->db, key);
                        val = NULL;
                    }
                }
            }
        }
        if (val != NULL) {
            if (!hasActiveChildProcess()) {
                if (server.maxmemory_policy & MAXMEMORY_FLAG_LFU) {
                    unsigned long counter = LFUDecrAndReturn(val);
                    counter = LFULogIncr(counter);
                    val->lru = (LFUGetTimeInMinutes()<<8) | counter;
                } else {
                    val->lru = LRU_CLOCK();
                }
            }
        }
        o = val;

        /* Non-existing key, move to next key. */
        if (o == NULL) continue;

        if (o->type != OBJ_ZSET) {
            addReplyErrorObject(c,shared.wrongtypeerr);
            return;
        }

        llen = zsetLength(o);
        /* Empty zset, move to next key. */
        if (llen == 0) continue;

        /* Non empty zset, this is like a normal ZPOP[MIN|MAX]. */
        pop_count = count;
        if (pop_count == -1) pop_count = 1;
        rangelen = (pop_count > (long)llen) ? (long)llen : pop_count;

        if (!use_nested_array) {
            /* BZPOPMIN/BZPOPMAX in RESP2 and RESP3. */
            addReplyArrayLen(c, rangelen * 2 + 1);
            addReplyBulk(c, key);
        } else {
            /* BZMPOP in RESP2 and RESP3. */
            addReplyArrayLen(c, 2);
            addReplyBulk(c, key);
            addReplyArrayLen(c, rangelen);
        }

        result_count = 0;
        do {
            if (o->encoding == OBJ_ENCODING_LISTPACK) {
                unsigned char *zl = o->ptr;
                unsigned char *eptr, *sptr;
                unsigned char *vstr;
                unsigned int vlen;
                long long vlong;

                /* Get the first or last element in the sorted set. */
                eptr = lpSeek(zl,where == ZSET_MAX ? -2 : 0);
                serverAssertWithInfo(c,o,eptr != NULL);
                vstr = lpGetValue(eptr,&vlen,&vlong);
                if (vstr == NULL)
                    ele = sdsfromlonglong(vlong);
                else
                    ele = sdsnewlen(vstr,vlen);

                /* Get the score. */
                sptr = lpNext(zl,eptr);
                serverAssertWithInfo(c,o,sptr != NULL);
                score = zzlGetScore(sptr);
            } else if (o->encoding == OBJ_ENCODING_SKIPLIST) {
                zset *zs = o->ptr;
                zskiplist *zsl = zs->zsl;
                zskiplistNode *zln;

                /* Get the first or last element in the sorted set. */
                zln = (where == ZSET_MAX ? zsl->tail :
                                           zsl->header->level[0].forward);

                /* There must be an element in the sorted set. */
                serverAssertWithInfo(c,o,zln != NULL);
                ele = sdsdup(zln->ele);
                score = zln->score;
            } else {
                serverPanic("Unknown sorted set encoding");
            }

            serverAssertWithInfo(c,o,zsetDel(o,ele));
            server.dirty++;

            if (result_count == 0) { /* Do this only for the first iteration. */
                char *events[2] = {"zpopmin","zpopmax"};
                notifyKeyspaceEvent(NOTIFY_ZSET,events[where],key,c->db->id);
                signalModifiedKey(c,c->db,key);
            }

            if (use_nested_array) {
                addReplyArrayLen(c,2);
            }
            addReplyBulkCBuffer(c,ele,sdslen(ele));
            addReplyDouble(c,score);
            sdsfree(ele);
            ++result_count;
        } while(--rangelen);

        /* Remove the key, if indeed needed. */
        if (zsetLength(o) == 0) {
            dbDelete(c->db,key);
            notifyKeyspaceEvent(NOTIFY_GENERIC,"del",key,c->db->id);
        }

        popcmd = (where == ZSET_MAX) ? shared.zpopmax : shared.zpopmin;
        if (count == -1) {
            /* Replicate it as ZPOP[MIN|MAX] instead of BZPOP[MIN|MAX]. */
            rewriteClientCommandVector(c,2, popcmd, key);
        } else {
            /* Replicate it as ZPOP[MIN|MAX] with COUNT option. */
            robj *count_obj = createStringObjectFromLongLong((count > (long)llen) ? (long)llen : count);
            rewriteClientCommandVector(c, 3, popcmd, key, count_obj);
            decrRefCount(count_obj);
        }

        return;
    }

    /* If we are not allowed to block the client and the zset is empty the only thing
     * we can do is treating it as a timeout (even with timeout 0). */
    if (c->flags & CLIENT_DENY_BLOCKING) {
        addReplyNullArray(c);
        return;
    }

    /* If the keys do not exist we must block */
    struct blockPos pos = {where};
    blockForKeys(c,BLOCKED_ZSET,c->argv+1,c->argc-2,count,timeout,NULL,&pos,NULL);
}

// BZPOPMIN key [key ...] timeout
void bzpopminCommand(client *c) {
    blockingGenericZpopCommand(c, c->argv+1, c->argc-2, ZSET_MIN, c->argc-1, -1, 0, 0);
}

// BZPOPMAX key [key ...] timeout
void bzpopmaxCommand(client *c) {
    blockingGenericZpopCommand(c, c->argv+1, c->argc-2, ZSET_MAX, c->argc-1, -1, 0, 0);
}

static void zrandmemberReplyWithListpack(client *c, unsigned int count, listpackEntry *keys, listpackEntry *vals) {
    for (unsigned long i = 0; i < count; i++) {
        if (vals && c->resp > 2)
            addReplyArrayLen(c,2);
        if (keys[i].sval)
            addReplyBulkCBuffer(c, keys[i].sval, keys[i].slen);
        else
            addReplyBulkLongLong(c, keys[i].lval);
        if (vals) {
            if (vals[i].sval) {
                addReplyDouble(c, zzlStrtod(vals[i].sval,vals[i].slen));
            } else
                addReplyDouble(c, vals[i].lval);
        }
    }
}

/* How many times bigger should be the zset compared to the requested size
 * for us to not use the "remove elements" strategy? Read later in the
 * implementation for more info. */
#define ZRANDMEMBER_SUB_STRATEGY_MUL 3

